+
+	reg = readl_relaxed(smmu->base + ARM_SMMU_IIDR);
+	smmu->features = smmu_iidr_features(reg, smmu->features);
+	if (!(smmu->features & ARM_SMMU_FEAT_NESTING))
+		return -ENXIO;
